                <h2>Importar GeoJSON</h2><p>Importe vários pontos, linhas ou polígonos de uma vez para uma camada existente.</p><form method="post" enctype="multipart/form-data" action="/<?=Format::h($slug)?>/territorio/importar" class="territorial-form"><input type="hidden" name="_token" value="<?=Format::h($token)?>"><div class="form-grid"><div class="field span-2"><label>Camada de destino</label><select name="camada_id" required><option value="">Selecione</option><?php foreach($camadas as$c):if(!(int)$c['ativo'])continue;?><option value="<?=$c['id']?>"><?=Format::h($c['nome'])?></option><?php endforeach;?></select></div><div class="field"><label>Secretaria</label><select name="secretaria_id"><option value="">Herdar / geral</option><?php foreach($secretarias as$s):?><option value="<?=$s['id']?>"><?=Format::h(($s['sigla']?$s['sigla'].' — ':'').$s['nome'])?></option><?php endforeach;?></select></div><div class="field"><label>Fase</label><select name="fase_id"><option value="">Sem vínculo</option><?php foreach($fases as$f):?><option value="<?=$f['id']?>">Fase <?=Format::h($f['ordem'])?> — <?=Format::h($f['aba'])?></option><?php endforeach;?></select></div><div class="field span-2"><label>Arquivo GeoJSON</label><input type="file" name="arquivo_geojson" accept=".geojson,.json,application/geo+json,application/json" required><small>Até 12 MB. Cada Feature será transformada em um objeto territorial.</small></div></div><div class="form-actions"><button class="btn primary">Importar objetos</button></div></form>
            </article>
            <article class="card territorial-config-card territorial-catalog-card"><h2>Camadas cadastradas</h2><div class="territorial-admin-list"><?php foreach($camadas as$c):?><div class="territorial-admin-row <?=!(int)$c['ativo']?'muted':''?>"><i style="--layer-color:<?=Format::h($c['cor'])?>"></i><div><b><?=Format::h($c['nome'])?></b><small><?=Format::h($c['categoria']?:'Sem categoria')?> · <?=Format::h($layerTypeLabel[$c['tipo_geometria']]??$c['tipo_geometria'])?> · <?=$c['objetos_ativos']?> objeto(s)</small></div><div class="actions"><a class="btn tiny secondary" href="/<?=Format::h($slug)?>/territorio?modo=configuracao&editar_camada=<?=$c['id']?>#territorialAdmin">Editar</a><form method="post" action="/<?=Format::h($slug)?>/territorio/camadas/<?=$c['id']?>/alternar"><input type="hidden" name="_token" value="<?=Format::h($token)?>"><button class="btn tiny <?=$c['ativo']?'off':'approve'?>"><?=$c['ativo']?'Desativar':'Ativar'?></button></form></div></div><?php endforeach;?><?php if(!$camadas):?><div class="empty-state">Nenhuma camada cadastrada.</div><?php endif;?></div></article>
        </div>

        <section class="card territorial-object-catalog" id="objetosTerritoriais">
            <div class="module-section-head"><div><h2>Objetos territoriais</h2><p>Catálogo de geometrias cadastradas na instância. Clique nos cabeçalhos para ordenar.</p></div><span class="module-context"><?=$objTotal?> registro(s)</span></div>
            <div class="table-scroll"><table class="config-table territorial-object-table sortable-territorial-table"><thead><tr>
                <?php foreach(['objeto'=>'Objeto','camada'=>'Camada','responsabilidade'=>'Responsabilidade','vinculo'=>'Vínculo','status'=>'Status'] as$key=>$label):?>
                    <th><a class="territorial-table-sort <?=$objSort===$key?'active':''?>" href="<?=Format::h($objSortHref($key))?>"><span><?=Format::h($label)?></span><i><?=$objSort===$key?($objDir==='asc'?'▲':'▼'):'↕'?></i></a></th>
                <?php endforeach;?>
                <th>Ações</th>
            </tr></thead><tbody><?php foreach($objItens as$o):?><tr class="<?=!(int)$o['ativo']?'muted-row':''?>"><td><b><?=Format::h($o['nome'])?></b><br><small><?=Format::h($o['endereco']?:$o['descricao'])?></small></td><td><span class="territorial-layer-chip"><i style="--layer-color:<?=Format::h($o['camada_cor'])?>"></i><?=Format::h($o['camada_nome'])?></span></td><td><?=Format::h(($o['secretaria_sigla']?:$o['secretaria_nome'])?:($o['camada_secretaria_sigla']?:($o['camada_secretaria_nome']?:'Geral')))?><?php if($o['departamento_nome']):?><br><small><?=Format::h($o['departamento_nome'])?></small><?php endif;?></td><td><?=Format::h($o['fase_id']?('Fase '.$o['fase_ordem'].' — '.$o['fase_aba']):'Sem fase vinculada')?></td><td><span class="territorial-status-tag <?=strtolower(Format::h($o['status']))?>"><?=Format::h($statusLabel[$o['status']]??$o['status'])?></span></td><td><div class="actions"><a class="btn tiny secondary" href="/<?=Format::h($slug)?>/territorio?modo=configuracao&editar_objeto=<?=$o['id']?>#territorialAdmin">Editar</a><form method="post" action="/<?=Format::h($slug)?>/territorio/objetos/<?=$o['id']?>/alternar"><input type="hidden" name="_token" value="<?=Format::h($token)?>"><button class="btn tiny <?=$o['ativo']?'off':'approve'?>"><?=$o['ativo']?'Desativar':'Ativar'?></button></form></div></td></tr><?php endforeach;?><?php if(!$objItens):?><tr><td colspan="6"><div class="empty-state">Nenhum objeto territorial cadastrado.</div></td></tr><?php endif;?></tbody></table></div>
            <div class="territorial-table-pagination">
                <div class="territorial-table-pagination-info"><?=$objTotal?'Exibindo '.($objInicio+1).' a '.min($objInicio+$objPorPagina,$objTotal).' de '.$objTotal.' registros':'Nenhum registro'?> · Página <?=$objPagina?> de <?=$objPaginas?></div>
                <nav class="territorial-table-pagination-nav" aria-label="Paginação dos objetos territoriais">
                    <?php if($objPagina>1):?><a class="territorial-page-link" href="<?=Format::h($objPageHref($objPagina-1))?>">‹ Anterior</a><?php else:?><span class="territorial-page-disabled">‹ Anterior</span><?php endif;?>
                    <?php $objPrev=0;foreach($objPaginasVisiveis as$p):if($objPrev&&$p>$objPrev+1):?><span class="territorial-page-ellipsis">…</span><?php endif;?><?php if($p===$objPagina):?><span class="territorial-page-current"><?=$p?></span><?php else:?><a class="territorial-page-link" href="<?=Format::h($objPageHref($p))?>"><?=$p?></a><?php endif;?><?php $objPrev=$p;endforeach;?>
                    <?php if($objPagina<$objPaginas):?><a class="territorial-page-link" href="<?=Format::h($objPageHref($objPagina+1))?>">Próxima ›</a><?php else:?><span class="territorial-page-disabled">Próxima ›</span><?php endif;?>
                </nav>
            </div>
        </section>
    </section>
    <?php endif;?>
</div>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script>
<script>
(function(){
 const el=document.getElementById('territorialIntelligenceMap');if(!el||typeof L==='undefined')return;
 const layers=<?=json_encode($mapLayers,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
 const objects=<?=json_encode($mapObjects,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
 const slug=<?=json_encode($slug)?>,mid=<?=(int)$tenant['id']?>;
 const fallback=[<?=json_encode((float)($tenant['latitude']?:-15))?>,<?=json_encode((float)($tenant['longitude']?:-52))?>];
 const map=L.map(el,{zoomControl:true,scrollWheelZoom:true}).setView(fallback,11);
 L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);
 let boundary=null;fetch('/media/municipios/'+mid+'/territorio',{credentials:'same-origin'}).then(r=>{if(!r.ok)throw new Error();return r.json()}).then(geo=>{boundary=L.geoJSON(geo,{style:{color:'#df4541',weight:2.2,opacity:1,fillColor:'#176fdd',fillOpacity:.06}}).addTo(map);const b=boundary.getBounds();if(b.isValid())map.fitBounds(b,{padding:[25,25]});}).catch(()=>{});
 const statusLabels={ATIVO:'Ativo',ATENCAO:'Atenção',CRITICO:'Crítico',CONCLUIDO:'Concluído',INATIVO:'Inativo'};
 const iconSymbols={pin:'📍',school:'▤',health:'✚',works:'◆',camera:'◉',area:'⬡'};
 const groupByLayer=new Map();layers.forEach(l=>groupByLayer.set(String(l.id),L.layerGroup().addTo(map)));
 const esc=v=>String(v??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[m]));
 const activeLayerIds=()=>new Set([...document.querySelectorAll('.layer-toggle:checked')].map(x=>x.value));
 const secFilter=document.getElementById('territorialSecretariaFilter'),statusFilter=document.getElementById('territorialStatusFilter'),phaseFilter=document.getElementById('territorialPhaseFilter'),visibleCount=document.getElementById('territorialVisibleCount');
 const detail=document.getElementById('territorialObjectDetail'),detailContent=document.getElementById('territorialObjectDetailContent'),focusObjectId=<?=json_encode($focusObjetoId)?>;
 function layerIcon(layer,size=34){const color=layer?.cor||'#176fdd',symbol=iconSymbols[layer?.icone]||iconSymbols.pin;return L.divIcon({className:'territorial-div-icon',html:`<span class="territorial-map-marker" style="--marker-color:${esc(color)}"><span>${esc(symbol)}</span></span>`,iconSize:[size,size+4],iconAnchor:[size/2,size+1],popupAnchor:[0,-size],tooltipAnchor:[0,-size/2]});}
 function popup(o){const layer=layers.find(l=>l.id===o.camada_id)||{},color=layer.cor||'#176fdd',symbol=iconSymbols[layer.icone]||iconSymbols.pin;let workflow=o.fase_id&&o.fase_acessivel?`<a class="territorial-popup-action" href="/${esc(slug)}/workflow/fase/${o.fase_id}">Abrir Workflow</a>`:'';const attrs=o.atributos&&typeof o.atributos==='object'?Object.entries(o.atributos).filter(([k,v])=>v!==null&&v!==''&&typeof v!=='object').slice(0,8):[];const attrHtml=attrs.length?`<div class="territorial-popup-extra"><b>Dados adicionais</b>${attrs.map(([k,v])=>`<span><small>${esc(String(k).replaceAll('_',' '))}</small><strong>${esc(String(v))}</strong></span>`).join('')}</div>`:'';const coords=Number.isFinite(Number(o.latitude))&&Number.isFinite(Number(o.longitude))?`<p class="territorial-popup-coords"><b>Coordenadas:</b> ${Number(o.latitude).toFixed(6)}, ${Number(o.longitude).toFixed(6)}</p>`:'';return `<div class="territorial-popup"><div class="territorial-popup-layer"><i style="background:${esc(color)}">${esc(symbol)}</i><span>${esc(layer.nome||'Camada')}</span></div><h3>${esc(o.nome)}</h3><div class="territorial-popup-topline"><span class="territorial-popup-status ${esc(String(o.status).toLowerCase())}">${esc(statusLabels[o.status]||o.status)}</span>${layer.categoria?`<span class="territorial-popup-category">${esc(layer.categoria)}</span>`:''}</div>${o.endereco?`<p><b>Endereço / referência:</b> ${esc(o.endereco)}</p>`:''}${o.secretaria?`<p><b>Secretaria:</b> ${esc(o.secretaria)}</p>`:''}${o.departamento?`<p><b>Departamento:</b> ${esc(o.departamento)}</p>`:''}${o.fase?`<p><b>Fase vinculada:</b> ${esc(o.fase)}</p>`:''}${o.descricao?`<div class="territorial-popup-description"><b>Descrição</b><p>${esc(o.descricao)}</p></div>`:''}${coords}${attrHtml}${workflow}</div>`;}
 function showDetails(o){if(!detail||!detailContent)return;detailContent.innerHTML=popup(o);detail.hidden=false;requestAnimationFrame(()=>detail.classList.add('open'));}
 function hideDetails(){if(!detail)return;detail.classList.remove('open');setTimeout(()=>{if(!detail.classList.contains('open'))detail.hidden=true;},160);}
 document.getElementById('territorialObjectDetailClose')?.addEventListener('click',hideDetails);
 function render(){groupByLayer.forEach(g=>g.clearLayers());hideDetails();const active=activeLayerIds();let count=0;objects.forEach(o=>{if(!o.ativo||!active.has(String(o.camada_id)))return;if(secFilter?.value&&String(o.secretaria_id||'')!==secFilter.value)return;if(statusFilter?.value&&o.status!==statusFilter.value)return;if(phaseFilter?.value&&String(o.fase_id||'')!==phaseFilter.value)return;const layerDef=layers.find(l=>l.id===o.camada_id)||{},color=layerDef.cor||'#176fdd';if(!o.geometry)return;const feature={type:'Feature',properties:{object_id:o.id},geometry:o.geometry};const geo=L.geoJSON(feature,{interactive:true,style:{color,weight:4,opacity:.98,fillColor:color,fillOpacity:.24},pointToLayer:(f,ll)=>L.marker(ll,{icon:layerIcon(layerDef),title:o.nome,riseOnHover:true,keyboard:true}),onEachFeature:(f,leafletLayer)=>{leafletLayer.bindTooltip(o.nome,{direction:'top',offset:[0,-18],opacity:.92});leafletLayer.on('click',e=>{showDetails(o);if(e.originalEvent)L.DomEvent.stopPropagation(e.originalEvent);});}});geo.addTo(groupByLayer.get(String(o.camada_id)));count++;});if(visibleCount)visibleCount.textContent=count;}
 document.querySelectorAll('.layer-toggle').forEach(x=>x.addEventListener('change',render));[secFilter,statusFilter,phaseFilter].forEach(x=>x?.addEventListener('change',render));document.getElementById('territorialClearFilters')?.addEventListener('click',()=>{if(secFilter)secFilter.value='';if(statusFilter)statusFilter.value='';if(phaseFilter)phaseFilter.value='';document.querySelectorAll('.layer-toggle').forEach(x=>x.checked=true);render();});
 document.getElementById('boundaryToggle')?.addEventListener('change',e=>{if(!boundary)return;e.target.checked?boundary.addTo(map):map.removeLayer(boundary)});render();if(focusObjectId){const focus=objects.find(o=>Number(o.id)===Number(focusObjectId));if(focus&&focus.geometry){showDetails(focus);try{if(focus.geometry.type==='Point'&&Array.isArray(focus.geometry.coordinates)){map.setView([Number(focus.geometry.coordinates[1]),Number(focus.geometry.coordinates[0])],17);}else{const helper=L.geoJSON({type:'Feature',properties:{},geometry:focus.geometry});const b=helper.getBounds();if(b.isValid())map.fitBounds(b,{padding:[55,55],maxZoom:17});}}catch(e){}}}
 const workspace=document.querySelector('.territorial-workspace');document.getElementById('territorialPanelToggle')?.addEventListener('click',()=>{workspace?.classList.toggle('sidebar-collapsed');setTimeout(()=>map.invalidateSize(),180)});
 const geometryInput=document.getElementById('territorialGeometryInput'),geometryState=document.getElementById('territorialGeometryState'),layerSelect=document.getElementById('territorialLayerSelect'),drawStatus=document.getElementById('territorialDrawStatus');let drawMode=null,drawPoints=[],draftLayer=null;
 function clearDraft(clearInput=false){if(draftLayer){map.removeLayer(draftLayer);draftLayer=null}drawPoints=[];drawMode=null;if(clearInput&&geometryInput)geometryInput.value='';if(geometryState&&clearInput)geometryState.textContent='Ainda não desenhada.';if(drawStatus)drawStatus.innerHTML='<b>Modo de desenho:</b> inativo.';}
 function currentLayerDef(){const id=Number(layerSelect?.value||0);return layers.find(l=>l.id===id)||{cor:'#6d32d9',icone:'pin'};}
 function showDraft(){if(draftLayer)map.removeLayer(draftLayer);if(!drawPoints.length)return;const ld=currentLayerDef(),c=ld.cor||'#6d32d9';if(drawMode==='point')draftLayer=L.marker(drawPoints[0],{icon:layerIcon(ld,36)}).addTo(map);else if(drawMode==='line')draftLayer=L.polyline(drawPoints,{color:c,weight:4}).addTo(map);else draftLayer=L.polygon(drawPoints,{color:c,weight:3,fillColor:c,fillOpacity:.18}).addTo(map);}
 function begin(mode){clearDraft(false);drawMode=mode;drawPoints=[];if(drawStatus)drawStatus.innerHTML='<b>Modo de desenho:</b> '+(mode==='point'?'Ponto — clique uma vez no mapa.':mode==='line'?'Linha — clique nos vértices e conclua.':'Polígono — clique nos vértices e conclua.');el.scrollIntoView({behavior:'smooth',block:'center'});}
 document.querySelectorAll('.draw-start').forEach(b=>b.addEventListener('click',()=>begin(b.dataset.draw)));
 map.on('click',e=>{if(!drawMode||!geometryInput)return;drawPoints.push(e.latlng);showDraft();if(drawMode==='point'){geometryInput.value=JSON.stringify({type:'Point',coordinates:[e.latlng.lng,e.latlng.lat]});geometryState.textContent='Ponto desenhado e pronto para salvar.';if(drawStatus)drawStatus.innerHTML='<b>Geometria:</b> ponto capturado.';drawMode=null;}});
 document.getElementById('territorialFinishDrawing')?.addEventListener('click',()=>{if(!geometryInput||!drawMode)return;if(drawMode==='line'){if(drawPoints.length<2){alert('Marque pelo menos dois pontos.');return}geometryInput.value=JSON.stringify({type:'LineString',coordinates:drawPoints.map(p=>[p.lng,p.lat])});}else if(drawMode==='polygon'){if(drawPoints.length<3){alert('Marque pelo menos três pontos.');return}const c=drawPoints.map(p=>[p.lng,p.lat]);c.push(c[0]);geometryInput.value=JSON.stringify({type:'Polygon',coordinates:[c]});}geometryState.textContent='Geometria desenhada e pronta para salvar.';if(drawStatus)drawStatus.innerHTML='<b>Geometria:</b> desenho concluído.';drawMode=null;});
 document.getElementById('territorialClearDrawing')?.addEventListener('click',()=>clearDraft(true));
 if(geometryInput?.value){try{const g=JSON.parse(geometryInput.value);draftLayer=L.geoJSON({type:'Feature',properties:{},geometry:g},{style:{color:'#6d32d9',weight:4,fillOpacity:.18},pointToLayer:(f,ll)=>L.marker(ll,{icon:layerIcon(currentLayerDef(),36)})}).addTo(map);const b=draftLayer.getBounds?.();if(b?.isValid())map.fitBounds(b,{padding:[35,35]});}catch(e){}}
 const addressInput=document.getElementById('territorialAddressInput'),geocodeButton=document.getElementById('territorialGeocodeButton'),geocodeStatus=document.getElementById('territorialGeocodeStatus'),geocodeResults=document.getElementById('territorialGeocodeResults');
 function layerGeometryType(){const opt=layerSelect?.selectedOptions?.[0];return String(opt?.dataset?.geometry||'').toUpperCase();}
 function applyGeocodeResult(r){if(!geometryInput)return;const lat=Number(r.lat),lng=Number(r.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng))return;clearDraft(false);drawMode=null;drawPoints=[L.latLng(lat,lng)];geometryInput.value=JSON.stringify({type:'Point',coordinates:[lng,lat]});draftLayer=L.marker([lat,lng],{icon:layerIcon(currentLayerDef(),38)}).addTo(map);map.setView([lat,lng],17);if(geometryState)geometryState.textContent='Ponto localizado pelo endereço e pronto para salvar.';if(drawStatus)drawStatus.innerHTML='<b>Geometria:</b> ponto obtido pelo endereço.';if(geocodeStatus){geocodeStatus.className='territorial-geocode-status success';geocodeStatus.textContent=(r.inside_municipio?'✓ ':'⚠ ')+(r.inside_municipio?'Endereço localizado dentro do município.':'Confira o ponto: resultado próximo ao limite municipal.');}}
 function renderGeocodeResults(results){if(!geocodeResults)return;geocodeResults.innerHTML='';if(!results?.length)return;results.forEach((r,i)=>{const b=document.createElement('button');b.type='button';b.className='territorial-geocode-result'+(i===0?' best':'');b.innerHTML=`<span>${esc(r.display_name||'Resultado')}</span><small>${r.inside_municipio?'Dentro do município':'Verificar localização'}</small>`;b.addEventListener('click',()=>applyGeocodeResult(r));geocodeResults.appendChild(b);});}
 async function geocodeAddress(){const address=String(addressInput?.value||'').trim();if(!address){if(geocodeStatus){geocodeStatus.className='territorial-geocode-status error';geocodeStatus.textContent='Informe um endereço antes de localizar.';}return;}const gt=layerGeometryType();if(gt&&gt!=='POINT'&&gt!=='MIXED'){if(geocodeStatus){geocodeStatus.className='territorial-geocode-status warning';geocodeStatus.textContent='A localização por endereço cria um ponto. Para esta camada, use o desenho manual ou uma camada do tipo Ponto/Mista.';}return;}geocodeButton.disabled=true;if(geocodeStatus){geocodeStatus.className='territorial-geocode-status loading';geocodeStatus.textContent='Localizando endereço…';}if(geocodeResults)geocodeResults.innerHTML='';try{const body=new URLSearchParams({_token:<?=json_encode($token)?>,endereco:address});const res=await fetch(`/${slug}/territorio/geocodificar`,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8','Accept':'application/json'},credentials:'same-origin',body:body.toString()});const data=await res.json();if(!res.ok||!data.ok)throw new Error(data.error||'Não foi possível localizar o endereço.');const results=Array.isArray(data.results)?data.results:[];if(!results.length)throw new Error('Nenhum endereço correspondente foi encontrado dentro do município.');renderGeocodeResults(results);applyGeocodeResult(results[0]);if(results.length>1&&geocodeStatus)geocodeStatus.textContent+=' Há alternativas abaixo caso o ponto não seja o correto.';}catch(e){if(geocodeStatus){geocodeStatus.className='territorial-geocode-status error';geocodeStatus.textContent=e?.message||'Não foi possível localizar o endereço.';}}finally{geocodeButton.disabled=false;}}
 geocodeButton?.addEventListener('click',geocodeAddress);addressInput?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();geocodeAddress();}});layerSelect?.addEventListener('change',()=>{const gt=layerGeometryType();if(geocodeButton)geocodeButton.disabled=!!gt&&gt!=='POINT'&&gt!=='MIXED';});
 const secSel=document.getElementById('territorialObjectSecretaria'),depSel=document.getElementById('territorialObjectDepartamento');function filterDepartments(){if(!depSel)return;const sid=secSel?.value||'';[...depSel.options].forEach((o,i)=>{if(i===0)return;o.hidden=!!sid&&o.dataset.secretaria!==sid;if(o.hidden&&o.selected)depSel.value='';});}secSel?.addEventListener('change',filterDepartments);filterDepartments();
 setTimeout(()=>map.invalidateSize(),120);window.addEventListener('resize',()=>map.invalidateSize(),{passive:true});if('ResizeObserver'in window)new ResizeObserver(()=>map.invalidateSize()).observe(el);
})();
</script>
